class InputError(Exception):
    pass


def read_rows(path: str) -> list[tuple[str, str]]:
    rows = []
    try:
        with open(path, encoding='utf-8-sig', newline='') as handle:
            reader = csv.reader(handle)
            header = next(reader, None)
            if header is None or [cell.strip() for cell in header] != ['date', 'description', 'amount']:
                raise InputError(f'{path}: bad header')
            for row in reader:
                if not row or (len(row) == 1 and not row[0].strip()):
                    continue
                where = f'{path}:{reader.line_num}'
                if len(row) != 3:
                    raise InputError(f'{where}: expected 3 columns, got {len(row)}')
                when, amount = row[0].strip(), row[2].strip()
                try:
                    month_of(when)
                    parse_amount(amount)
                except ValueError as error:
                    raise InputError(f'{where}: {error}') from None
                rows.append((when, amount))
    except (OSError, UnicodeDecodeError, csv.Error) as error:
        raise InputError(f'{path}: {error}') from None
    return rows


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(prog='tally.py')
    parser.add_argument('files', nargs='+', metavar='FILE')
    args = parser.parse_args(argv)
    rows = []
    try:
        for path in args.files:
            rows.extend(read_rows(path))
    except InputError as error:
        print(f'tally: {error}', file=sys.stderr)
        return 1
    for line in format_totals(tally(rows)):
        print(line)
    return 0


if __name__ == '__main__':
    sys.exit(main())
